composio run '
  const res = await execute("SLACK_SEND_MESSAGE", { channel: "#general", text: "build passed" });
  console.log(JSON.stringify(res, null, 2));
  console.log("timestamp:", res.data?.ts ?? res.data?.message?.ts ?? "not found");
'

